import { createHash } from 'node:crypto';

export function verificationKey(executor, benchmarkDigest) {
  return createHash('sha256').update(JSON.stringify({executor, benchmarkDigest})).digest('hex');
}

export async function verifyBenchmark({ executor, benchmarkDigest, cache, execute }) {
  const result = await execute();
  return { source: 'fresh', result, uncovered: [] };
}

