import assert from 'node:assert/strict';
import { test } from 'node:test';
import { observeExecutor } from '../src/executor.mjs';
import { verifyBenchmark } from '../src/verification.mjs';

test('benchmark validates actual resident memory', async () => {
  const executor = observeExecutor({runtimeVersion: process.version, imageId: 'synthetic-node'});
  const outcome = await verifyBenchmark({
    executor, benchmarkDigest: 'benchmark-v1', cache: new Map(),
    execute: async () => {
      assert.ok(process.memoryUsage.rss() > 0);
      return 'checked';
    }
  });
  assert.equal(outcome.result, 'checked');
});

