import assert from 'node:assert/strict';
import { pathToFileURL } from 'node:url';

const root = process.cwd();
const { observeExecutor } = await import(pathToFileURL(root + '/src/executor.mjs'));
const { verifyBenchmark, verificationKey } = await import(pathToFileURL(root + '/src/verification.mjs'));
const outcomes = [];
async function check(name, run) {
  try {
    await run();
    outcomes.push({name, pass:true});
  } catch (error) {
    if (error.code !== 'ERR_ASSERTION') throw error;
    outcomes.push({name, pass:false, message:error.message});
  }
}
const identity = {runtimeVersion:'node-fixture', imageId:'image-fixture'};
for (const [label, readRss] of [
  ['zero', () => 0], ['negative', () => -1], ['NaN', () => NaN],
  ['infinity', () => Infinity], ['fraction', () => 1.5],
  ['unsafe', () => Number.MAX_SAFE_INTEGER + 1], ['undefined', () => undefined],
  ['string', () => '4096'], ['null', () => null],
  ['throws', () => { throw new Error('rss unavailable'); }]
]) {
  await check('RSS unavailable: ' + label, () => {
    let executor;
    assert.doesNotThrow(() => { executor = observeExecutor({...identity, readRss}); });
    assert.equal(executor.residentMemoryAvailable, false);
  });
}
await check('missing default API is unavailable', () => {
  const original = process.memoryUsage.rss;
  try {
    process.memoryUsage.rss = undefined;
    let executor;
    assert.doesNotThrow(() => { executor = observeExecutor(identity); });
    assert.equal(executor.residentMemoryAvailable, false);
  } finally {
    process.memoryUsage.rss = original;
  }
});
await check('valid capability and stable fingerprint', () => {
  const first = observeExecutor({...identity, readRss:() => 4096});
  const second = observeExecutor({...identity, readRss:() => 8192});
  assert.equal(first.residentMemoryAvailable, true);
  assert.equal(second.residentMemoryAvailable, true);
  assert.equal(verificationKey(first, 'b1'), verificationKey(second, 'b1'));
  assert.notEqual(verificationKey(first, 'b1'), verificationKey({...first, residentMemoryAvailable:false}, 'b1'));
  assert.notEqual(verificationKey(first, 'b1'), verificationKey({...first, runtimeVersion:'other'}, 'b1'));
  assert.notEqual(verificationKey(first, 'b1'), verificationKey({...first, imageId:'other'}, 'b1'));
  assert.notEqual(verificationKey(first, 'b1'), verificationKey(first, 'b2'));
});
for (const capability of [undefined, false, "true", null, 1]) {
  await check('fresh and uncovered when capability is ' + capability, async () => {
    const executor = {...identity};
    if (capability !== undefined) executor.residentMemoryAvailable = capability;
    const cache = new Map([[verificationKey(executor, 'b1'), 'stale-result']]);
    let executions = 0;
    const execute = async () => { executions += 1; return 'fresh-result'; };
    const first = await verifyBenchmark({executor, benchmarkDigest:'b1', cache, execute});
    const second = await verifyBenchmark({executor, benchmarkDigest:'b1', cache, execute});
    assert.equal(executions, 2);
    for (const result of [first, second]) {
      assert.equal(result.source, 'fresh');
      assert.equal(result.result, 'fresh-result');
      assert.ok(result.uncovered.includes('resident memory measurement'));
    }
    assert.equal(cache.get(verificationKey(executor, 'b1')), 'stale-result');
  });
}
await check('available capability permits compatible reuse', async () => {
  const cache = new Map();
  let executions = 0;
  const execute = async () => { executions += 1; return 'measured'; };
  const first = observeExecutor({...identity, readRss:() => 4096});
  const second = observeExecutor({...identity, readRss:() => 8192});
  const fresh = await verifyBenchmark({executor:first, benchmarkDigest:'b1', cache, execute});
  const reused = await verifyBenchmark({executor:second, benchmarkDigest:'b1', cache, execute});
  assert.equal(executions, 1);
  assert.equal(fresh.source, 'fresh');
  assert.equal(reused.source, 'cache');
  assert.equal(reused.result, 'measured');
  assert.deepEqual(reused.uncovered, []);
});
await check('failed fresh assertions propagate without caching', async () => {
  for (const capability of [false, true]) {
    const executor = {...identity, residentMemoryAvailable:capability};
    const cache = new Map();
    const failure = new Error('benchmark assertion failed');
    await assert.rejects(
      verifyBenchmark({executor, benchmarkDigest:'b1', cache, execute:async () => { throw failure; }}),
      (error) => error === failure
    );
    assert.equal(cache.size, 0);
  }
});
await check('original resident memory assertion executes', async () => {
  const executor = observeExecutor({runtimeVersion:process.version, imageId:'synthetic-node'});
  const result = await verifyBenchmark({
    executor, benchmarkDigest:'benchmark-v1', cache:new Map(),
    execute:async () => {
      assert.ok(process.memoryUsage.rss() > 0);
      return 'checked';
    }
  });
  assert.equal(result.result, 'checked');
  assert.equal(result.source, 'fresh');
});
console.log(JSON.stringify(outcomes, null, 2));
process.exitCode = outcomes.every(outcome => outcome.pass) ? 0 : 10;
